/**
 * ConsentForm Component
 * Renders a form with a single consent checkbox and a submit button.
 */
function ConsentForm() {
  const handleSubmit = (event) => {
    event.preventDefault();
    const formData = new FormData(event.target);
    const consent = formData.get('consent');

    if (consent) {
      alert('Thank you for your consent!');
      console.log('Form submitted successfully');
    }
  };

  return `
    <div class="container">
      <h1>Terms of Use</h1>
      <form id="consent-form">
        <div class="form-field">
          <label class="checkbox-container">
            <input 
              type="checkbox" 
              name="consent" 
              id="consent-checkbox" 
              required 
              aria-describedby="consent-helper"
            />
            <span class="checkbox-label">I agree to the Terms of Use</span>
          </label>
          <span id="consent-helper" class="helper-text">
            You must agree to continue using our services.
          </span>
        </div>
        <button type="submit">Submit</button>
      </form>
    </div>
  `;
}

// "Mount" the component
document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('root');
  root.innerHTML = ConsentForm();

  // Attach event listeners after rendering
  const form = document.getElementById('consent-form');
  form.addEventListener('submit', (e) => {
    // In a real React app, this would be handled via state/props
    // but here we attach it manually to the DOM.
    const checkbox = document.getElementById('consent-checkbox');
    if (checkbox.checked) {
      alert('Thank you for your consent!');
    }
    e.preventDefault();
  });
});

